ai.format:
Scene of the 2D physics lab (module “Physics lab”) — JSON. The engine is ready (rigid bodies, collisions, friction, bounces, hinges, ropes, rods, springs, pulleys, liquids with pressure and buoyancy); the scene only says WHAT stands in it.
Units: metres, kilograms, seconds; y grows upwards, the ground at y = 0. Every number may be an expression "=…" with values drawn in "vars" (e.g. "=4*tan(rad(kat))").

"world": { "gravity": 9.81, "air": 1 (air resistance, 0 — vacuum), "depth": 0.1 (thickness of the bodies — gives their mass), "ground": true, "speed": 1 }
"vars": [{ "name": "kat", "from": 15, "to": 40, "step": 5 }] or { "name": "ciecz", "pick": ["water", "oil"] } — different every time; in texts "{kat}"
"bodies": [{ "id", "label", "shape": "circle" (r) | "box" (w, h) | "poly" (points [[x,y],…], convex), "x", "y", "angle" (degrees), "material", "density", "friction", "bounce", "static": true (fixed), "vx", "vy", "spin", "drag": false (cannot be grabbed), "trace": true (trace), "color" }]
  materials: {materials}
"joints": [{ "type": "pin" (axle at the point "at"; with "torque" and "speed" — a motor) | "rod" | "rope" | "spring" ("k" N/m, "damping") | "pulley" ("a", "b", wheels at "at" and "at2"), "a": id, "b": id (omitted — attached to the world), "on": [x, y] (point on "a", relative to its centre), "at": [x, y] (point in the world or on "b"), "length" }]
"fluids": [{ "id", "x", "y" (lower left corner of the inside), "w", "h", "wall", "layers": [{ "liquid", "height" }] (from the bottom; lighter ones rise by themselves), "holes": [{ "side": "left"|"right"|"bottom", "at" (height above the bottom), "size", "open" }] }] — liquids: {liquids}
"pipes": [{ "a", "b", "y", "size", "open" }] — a pipe joining two tanks (communicating vessels)
"show": { "vectors": [{vectors}] (v — velocity, g — weight, lift — buoyancy, net — net force), "trace": [id], "grid", "pressure" (pressure as a colour of depth), "values" (masses, forces) }
"graph": { "body": id, "of": [{graph}] } — a chart over time (h height, v speed, ek/ep/e energies)
"allow": { "add": false, "palette": [{palette}], "tools": [{tools}], "edit", "drag" }
"controls": [{controls}] — world switches in the panel
"goal": { "body": id, "area": [x0, y0, x1, y1], "for": 0.5, "say": "You did it!" } — a goal (e.g. the ball in the basket)
"steps": [{ "say": "…", "do": "play" | "pause" | { "open": tankId, "hole": 0 } | { "push": id, "vx": 2, "vy": 0 }, "wait": 3 }] — steps; “Show” performs them in order
"view": [x0, y0, x1, y1] — what is visible at the start
